    lch_actFailedDetail: ['{on} of its ads and ad sets were switched on; {off} couldn’t be. Activate again to retry.', '{on} van de advertenties en advertentiesets zijn aangezet; {off} lukte niet. Activeer opnieuw om het nog eens te proberen.', '{on} ihrer Anzeigen und Anzeigengruppen wurden eingeschaltet; {off} nicht. Aktiviere erneut, um es noch einmal zu versuchen.', '{on} de ses annonces et ensembles de publicités ont été activés ; {off} n’ont pas pu l’être. Activez à nouveau pour réessayer.', 'Se activaron {on} de sus anuncios y conjuntos de anuncios; {off} no se pudieron activar. Vuelve a activarla para reintentarlo.', '{on} dos anúncios e conjuntos de anúncios foram ativados; {off} não foi possível. Ative de novo para tentar outra vez.'],
    lch_actTimeout: ['{platform} didn’t answer in time. The campaign is still paused — check it in Campaigns before activating again.', '{platform} antwoordde niet op tijd. De campagne is nog gepauzeerd — controleer het in Campagnes voordat je opnieuw activeert.', '{platform} hat nicht rechtzeitig geantwortet. Die Kampagne ist weiter pausiert — prüfe sie unter Kampagnen, bevor du erneut aktivierst.', '{platform} n’a pas répondu à temps. La campagne est toujours en pause — vérifiez-la dans Campagnes avant de l’activer à nouveau.', '{platform} no respondió a tiempo. La campaña sigue en pausa: revísala en Campañas antes de volver a activarla.', 'O {platform} não respondeu a tempo. A campanha continua em pausa — verifique-a em Campanhas antes de ativar de novo.'],
    lch_actBusy: ['This campaign is already being activated. Wait a moment.', 'Deze campagne wordt al geactiveerd. Wacht even.', 'Diese Kampagne wird bereits aktiviert. Warte einen Moment.', 'Cette campagne est déjà en cours d’activation. Patientez un instant.', 'Esta campaña ya se está activando. Espera un momento.', 'Esta campanha já está a ser ativada. Aguarde um momento.'],
    lch_actWrongAccount: ['This campaign was published to another ad account than the one connected now. Switch the ad account in Connections, then try again. Nothing was changed.', 'Deze campagne is gepubliceerd in een ander advertentieaccount dan het account dat nu gekoppeld is. Wissel het advertentieaccount in Connecties en probeer het opnieuw. Er is niets veranderd.', 'Diese Kampagne wurde in einem anderen Werbekonto veröffentlicht als dem jetzt verbundenen. Wechsle das Werbekonto unter Verbindungen und versuche es erneut. Es wurde nichts geändert.', 'Cette campagne a été publiée sur un autre compte publicitaire que celui connecté. Changez de compte dans Connexions, puis réessayez. Rien n’a été modifié.', 'Esta campaña se publicó en otra cuenta publicitaria distinta de la conectada ahora. Cambia la cuenta en Conexiones e inténtalo de nuevo. No se cambió nada.', 'Esta campanha foi publicada noutra conta de anúncios que não a ligada agora. Mude a conta em Ligações e tente de novo. Nada foi alterado.'],
    lch_actNotFound: ['This campaign wasn’t found in the ad account that is connected now. Nothing was changed.', 'Deze campagne is niet gevonden in het advertentieaccount dat nu gekoppeld is. Er is niets veranderd.', 'Diese Kampagne wurde im jetzt verbundenen Werbekonto nicht gefunden. Es wurde nichts geändert.', 'Cette campagne est introuvable dans le compte publicitaire connecté. Rien n’a été modifié.', 'Esta campaña no se encontró en la cuenta publicitaria conectada ahora. No se cambió nada.', 'Esta campanha não foi encontrada na conta de anúncios ligada agora. Nada foi alterado.'],
